#include <stdint.h>
#include <string.h>

typedef struct {
    int x, y;
} Point;

void radix_sort(uint64_t *arr, int n) {
    uint64_t *temp = (uint64_t*)malloc(n * sizeof(uint64_t));
    int count[65536];
    for (int shift = 0; shift < 64; shift += 16) {
        memset(count, 0, sizeof(count));
        for (int i = 0; i < n; i++) {
            count[(arr[i] >> shift) & 0xFFFF]++;
        }
        int sum = 0;
        for (int i = 0; i < 65536; i++) {
            int c = count[i];
            count[i] = sum;
            sum += c;
        }
        for (int i = 0; i < n; i++) {
            int digit = (arr[i] >> shift) & 0xFFFF;
            temp[count[digit]++] = arr[i];
        }
        memcpy(arr, temp, n * sizeof(uint64_t));
    }
    free(temp);
}

