        scanf("%d %d", &pts[i].x, &pts[i].y);
    }
    int M = N * N;
    uint64_t *edges = (uint64_t*)malloc(M * sizeof(uint64_t));
    int idx = 0;
    for (int u = 0; u <= N; u++) {
        for (int v = 1; v <= N; v++) {
