            long long dy = pts[u].y - pts[v].y;
            long long w = dx*dx + dy*dy;
            uint64_t key = ((uint64_t)w << 22) | ((uint64_t)u << 11) | (uint64_t)v;
            edges[idx++] = key;
        }
    }
    radix_sort(edges, M);
