    int *touched = (int*)malloc((N+1) * sizeof(int));
    for (int i = 0; i <= N; i++) {
        best[i] = -1;
        best2[i] = -1;
    }
    best[0] = 0;
    int ans = 0;
    int i = M - 1;
    while (i >= 0) {
        uint64_t key = edges[i];
        int w = (int)(key >> 22);
        int j = i;
        while (j >= 0 && (int)(edges[j] >> 22) == w) {
            j--;
        }
        int tcount = 0;
        for (int k = j + 1; k <= i; k++) {
            uint64_t e = edges[k];
            int u = (int)((e >> 11) & 0x7FF);
            int v = (int)(e & 0x7FF);
            if (best[u] >= 0) {
                int dp = best[u] + 1;
                if (dp > best2[v]) {
                    if (best2[v] == -1) {
                        touched[tcount++] = v;
                    }
                    best2[v] = dp;
                }
                if (dp > ans) ans = dp;
            }
        }
        for (int t = 0; t < tcount; t++) {
            int v = touched[t];
            if (best2[v] > best[v]) best[v] = best2[v];
            best2[v] = -1;
        }
        i = j;
    }
    printf("%d\n", ans);
    free(edges);
    free(best);
    free(best2);
    free(touched);
    return 0;
}
